preConditionHook:
// MA WICK TOUCHES HOLD SIDE (Brian's notes ON-71, #71): the last
// touchCount EMA touches were wick-only with the body above (long) /
// below (short). Counters persist; only touch bars update them.
// MultiWalk's WFSafe_Xaverage, ported unchanged from EmaGapBar (the EMA
// reference, with the measurements): price seed on the first calculated bar
// (ctx.CurrentBar() == 1), recurrence x + sf*(p - x) in ONE statement,
// sf = 2/(Length+1) from the raw input every bar, state carried on a length
// change (EL_XAverage_Lag_Probe.txt, 2026-09-17).
emaSf = 2.0 / (emaLength + 1.0);
if (ctx.CurrentBar() == 1) {
    emaVal = close[0];
} else {
    emaVal = emaVal + emaSf * (close[0] - emaVal);
}
if (el_le(low[0], emaVal) && el_ge(high[0], emaVal)) {
    if (el_gt(open[0], emaVal) && el_gt(close[0], emaVal)) {
        upRun = upRun + 1;
    } else {
        upRun = 0;
    }
    if (el_lt(open[0], emaVal) && el_lt(close[0], emaVal)) {
        downRun = downRun + 1;
    } else {
        downRun = 0;
    }
}
